// Ambient extensions to the generated `Env` type (worker-configuration.d.ts).
//
// `worker-configuration.d.ts` is regenerated by `npx wrangler types` and only
// includes fields for bindings/vars actually declared in wrangler.toml.
// Secrets (SPOTIFY_CLIENT_ID, SPOTIFY_CLIENT_SECRET, TOKEN_ENCRYPTION_KEY, ...)
// are intentionally never declared in wrangler.toml — they're set out-of-band
// via `wrangler secret put` so their real values are never committed. That
// means they never appear in the generated Env type either.
//
// This file merges the missing fields into the same ambient `Env` interface
// so the rest of the codebase can reference `env.SPOTIFY_CLIENT_ID` etc. with
// full type safety, without touching the generated file or wrangler.toml.
//
// As more secrets are introduced in later tasks (SEED_SECRET, R2_* secrets,
// RESEND_API_KEY, SENTRY_DSN, ...), add them here.
interface Env {
  SPOTIFY_CLIENT_ID: string;
  SPOTIFY_CLIENT_SECRET: string;
  TOKEN_ENCRYPTION_KEY: string;
  SEED_SECRET: string;
}

// `cloudflare:test`'s `env` export is typed as `Cloudflare.Env` (a separate
// ambient interface from the top-level `Env` above, both generated into
// worker-configuration.d.ts) — it needs the same merge so tests that pass
// `env` from `cloudflare:test` into `worker.fetch(req, env, ctx)` typecheck.
declare namespace Cloudflare {
  interface Env {
    SPOTIFY_CLIENT_ID: string;
    SPOTIFY_CLIENT_SECRET: string;
    TOKEN_ENCRYPTION_KEY: string;
    SEED_SECRET: string;
  }
}
